import numpy as np
import numba

@numba.njit(cache=True)
def _project_simplex(y):
    n = len(y)
    sorted_y = np.sort(y)[::-1]
    cumsum = 0.0
    rho = 0
    for i in range(n):
        cumsum += sorted_y[i]
        if sorted_y[i] > (cumsum - 1.0) / (i + 1.0):
            rho = i
    cumsum2 = 0.0
    for i in range(rho + 1):
        cumsum2 += sorted_y[i]
    theta = (cumsum2 - 1.0) / (rho + 1.0)
    x = np.empty(n)
    for i in range(n):
        val = y[i] - theta
        x[i] = val if val > 0.0 else 0.0
    return x

class Solver:
    def __init__(self):
        _project_simplex(np.array([1.0, 2.0]))

    def solve(self, problem, **kwargs):
        y = np.asarray(problem["y"], dtype=np.float64).ravel()
        x = _project_simplex(y)
        return {"solution": x}
